def amicable_numbers_sum(limit):
    def sum_of_proper_divisors(n):
        """Calculate the sum of proper divisors of n."""
        if n < 2:
            return 0  # 1 has no proper divisors
        divisors_sum = 1  # 1 is always a proper divisor
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                divisors_sum += i
                if i != n // i:  # Add the pair divisor, if it's not the square root
                    divisors_sum += n // i
        return divisors_sum

    amicable_sum = 0
    visited = set()  # To track numbers already processed in amicable pairs

    for a in range(2, limit + 1):
        if a not in visited:
            b = sum_of_proper_divisors(a)
            if b != a and b <= limit and sum_of_proper_divisors(b) == a:
                amicable_sum += a + b
                visited.add(a)
                visited.add(b)

    return amicable_sum

# Example test case:
assert amicable_numbers_sum(999) == 504
