def reverse_vowels(s: str) -> str:
    # Define the set of vowels (case-insensitive, excluding 'y')
    vowels = {'a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U'}

    # Convert the string to a list for mutable operations
    s_list = list(s)

    # Initialize two pointers
    left, right = 0, len(s) - 1

    while left < right:
        # Move the left pointer until it points to a vowel
        while left < right and s_list[left] not in vowels:
            left += 1
        # Move the right pointer until it points to a vowel
        while left < right and s_list[right] not in vowels:
            right -= 1

        # Swap the vowels at the left and right pointers
        if left < right:
            s_list[left], s_list[right] = s_list[right], s_list[left]
            left += 1
            right -= 1

    # Join the list back into a string and return it
    return ''.join(s_list)
