def maximize_elements(tuple1, tuple2):
    """
    Takes two tuples of tuples and returns a new tuple of tuples where the maximum 
    element at each position is chosen from the corresponding tuples of the input.
    """
    # Check if the lengths of the input tuples are the same
    if len(tuple1) != len(tuple2):
        raise ValueError("Input tuples must have the same length")

    # Check if all inner tuples have the same length
    if any(len(t1) != len(t2) for t1, t2 in zip(tuple1, tuple2)):
        raise ValueError("Corresponding inner tuples must have the same length")

    # Use zip to iterate through corresponding tuples from both inputs
    return tuple(
        tuple(max(a, b) for a, b in zip(t1, t2))  # Find max element-wise
        for t1, t2 in zip(tuple1, tuple2)         # Iterate through corresponding tuples
    )

# Example usage and assertions
assert maximize_elements(((1, 3), (4, 5), (2, 9), (1, 10)), ((6, 7), (3, 9), (1, 1), (7, 3))) == ((6, 7), (4, 9), (2, 9), (7, 10))
assert maximize_elements(((1, 2), (3, 4)), ((5, 6), (7, 8))) == ((5, 6), (7, 8))
assert maximize_elements((), ()) == ()  # Empty inputs
try:
    maximize_elements(((1, 2), (3, 4)), ())  # One input is empty
except ValueError as e:
    assert str(e) == "Input tuples must have the same length"
try:
    maximize_elements(((1, 3, 5),), ((2, 2),))  # Tuples of different lengths
except ValueError as e:
    assert str(e) == "Corresponding inner tuples must have the same length"
