def start_withp(word_list):
    # List to store words starting with 'P'
    p_words = []

    # Iterate through each string in the input list
    for sentence in word_list:
        # Split the string into words
        words = sentence.split()
        # Check each word
        for word in words:
            # Check if the word starts with 'P' (case-sensitive as per example)
            if word.startswith('P'):
                p_words.append(word)
                # Stop if we already have two words
                if len(p_words) == 2:
                    return tuple(p_words)

    # Return the result as a tuple (can be empty or contain 1 word if < 2 words found)
    return tuple(p_words)
