def remove_uppercase(s: str) -> str:
    result = []
    inside_uppercase = False

    for char in s:
        if char.isupper():
            inside_uppercase = True  # Start or continue an uppercase substring
        elif inside_uppercase:
            inside_uppercase = False  # End an uppercase substring
            result.append(char)  # Add the first non-uppercase character after an uppercase substring
        else:
            result.append(char)  # Add non-uppercase character to result

    return ''.join(result)
