def find_kth(arr1, arr2, k):
    """
    Function to find the k-th element from two sorted arrays.
    Uses a binary search approach to find the k-th element efficiently.
    """
    def kth_in_two_sorted_arrays(arr1, arr2, k):
        len1, len2 = len(arr1), len(arr2)

        # Ensure arr1 is the smaller array
        if len1 > len2:
            return kth_in_two_sorted_arrays(arr2, arr1, k)

        # Handle empty array edge case
        if len1 == 0:
            return arr2[k - 1]

        # Handle k == 1 edge case
        if k == 1:
            return min(arr1[0], arr2[0])

        # Partition the arrays
        idx1 = min(len1, k // 2)  # Number of elements to pick from arr1
        idx2 = k - idx1          # Number of elements to pick from arr2
        mid1, mid2 = arr1[idx1 - 1], arr2[idx2 - 1]

        if mid1 < mid2:
            # Exclude first idx1 elements of arr1 and adjust k
            return kth_in_two_sorted_arrays(arr1[idx1:], arr2, k - idx1)
        else:
            # Exclude first idx2 elements of arr2 and adjust k
            return kth_in_two_sorted_arrays(arr1, arr2[idx2:], k - idx2)

    # Validate input
    if not (1 <= k <= len(arr1) + len(arr2)):
        raise ValueError("k is out of bounds of the combined arrays")

    return kth_in_two_sorted_arrays(arr1, arr2, k)

# Test cases
