assert find_kth([1, 2, 3], [4, 5, 6], 4) == 4
assert find_kth([1, 3], [2], 2) == 2
assert find_kth([], [1, 2, 3, 4], 3) == 3
assert find_kth([1, 2, 8], [3, 4, 5, 6, 7], 4) == 4
assert find_kth([1, 3, 5], [2, 4, 6, 8, 10], 7) == 8
