def tuple_to_dict(input_tuple):
    """
    Converts a tuple into a dictionary using adjacent elements as key-value pairs.

    Args:
    input_tuple (tuple): Input tuple to convert.

    Returns:
    dict: Dictionary with adjacent elements as key-value pairs.
    """
    # Validate input type
    if not isinstance(input_tuple, tuple):
        raise TypeError("Input must be a tuple")

    # Ensure the tuple has an even number of elements to form complete pairs
    if len(input_tuple) % 2 != 0:
        # Discard the last element if the tuple has an odd number of elements
        input_tuple = input_tuple[:-1]

    # Create dictionary using adjacent elements as key-value pairs
    result_dict = {input_tuple[i]: input_tuple[i + 1] for i in range(0, len(input_tuple), 2)}

    return result_dict

# Example usage and tests
assert tuple_to_dict((1, 5, 7, 10, 13, 5)) == {1: 5, 7: 10, 13: 5}
assert tuple_to_dict(()) == {}
assert tuple_to_dict((1,)) == {}
assert tuple_to_dict((1, 2, 3)) == {1: 2}
assert tuple_to_dict((1, 2, 3, 4, 5)) == {1: 2, 3: 4}
